cat > "C:/Users/User1/AppData/Local/Temp/claude/C--Users-User1-Desktop-dark-raiders/8a09e991-b4f4-4b23-b10f-ded92e837fc3/scratchpad/mk-cw-flashlight.ps1" <<'EOF'
$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "      put\(wspr,F\.x,F\.y,frr,2\*a\*\.9\*fr\);"
$r1="      put(gfxLightSpr(F.c||'#ffc27a','map'),F.x,F.y,frr,2*a*.9*fr);   // v34.73 (cw-flashlight): the flash lights the ground in the colour it already stores (his 10-12 graphics list)"
$a2="      put\(wspr,E\.x,E\.y,er,2\*a\*\.34\);"
$r2="      put(gfxLightSpr(E.kind==='raider'?'#ff8a6a':'#ff4a32','map'),E.x,E.y,er,2*a*.34);   // v34.73 (cw-flashlight): the same red as the eye glow"
$a3="put\(wspr,az\.x,az\.y,k,2\*a\*\(inb\?\.62:\.30\)\);"
$r3="put(gfxLightSpr('#4de3d0','map'),az.x,az.y,k,2*a*(inb?.62:.30));   // v34.73 (cw-flashlight): the beacon throws teal"
$chk=@'
  {v:'VER',what:'a flash lights the ground in its own colour in the light map (not plain white), and plain white again under CLASSIC lighting',
   run:function(){
     var PR=CanvasRenderingContext2D.prototype, od=PR.drawImage, g=null, hit=0, spr=null, gl0=CFG.gfxLight, bad=[], c='#ff3a9a', n0;
     function run(){
       var h=0; hit=0;
       PR.drawImage=function(im){ if(spr&&im===spr&&this===LMAP.x) hit++; return od.apply(this,arguments); };
       try{ g.flashes.push({x:g.player.x+40,y:g.player.y,r:160,c:c,t:0,life:9}); for(var f=0;f<3;f++) __loop(performance.now()+f*16.7); }
       finally{ PR.drawImage=od; }
       return hit;
     }
     try{
       __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       g=__state(); if(!g||!g.player) return 'SKIP: no raid';
       g.ents.length=0; g.player.iv=99; P.cond='night';
       if(isDay()) return 'SKIP: the raid would not go dark';
       if(typeof gfxLightSpr!=='function'||typeof LMAP==='undefined') return 'SKIP: no light map';
       spr=gfxLightSpr(c,'map');
       CFG.gfxLight=2; g.flashes.length=0;
       if(run()<1) bad.push('a '+c+' flash was not stamped in its own colour in the light map');
       CFG.gfxLight=0; g.flashes.length=0;
       if(run()>0) bad.push('the coloured stamp was drawn under CLASSIC lighting');
       return bad.length?bad.join('; '):null;
     } finally {
       PR.drawImage=od; CFG.gfxLight=gl0;
       try{ __endRaid('abandon'); }catch(_e){}
       __topClear();
     } }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='FLASHES AND MACHINE EYES LIGHT THE GROUND IN THEIR OWN COLOUR'
  why='His 10-12 graphics list (gfx9, coloured light) was half done: lamps lit the light map in colour but every flash, hunting machine and the extraction beacon was stamped plain white. Each now uses the colour it already stores, the same one the glow pass draws. The draw count is unchanged (cached sprite per colour), reduced flashing is untouched, his lamp and the teammate lamp stay white. Watch: at night a blast, cryo or acid tints the street, hunting machines throw red, the beacon teal.'
  now='At night blasts, shots, hunting machines and the beacon light the ground in their own colour.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 }, [ordered]@{ anchor=$a2; replacement=$r2 }, [ordered]@{ anchor=$a3; replacement=$r3 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-flashlight.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
EOF
cd "C:/claudecode/dark raiders"; bash tools/handoff/preflight.sh b cw-flashlight 2>&1 | tail -15
